const fa = await agent(`Du bist Finanzamt-Agent (Fachbereich Lohnsteuer/Sachbezüge). Beurteile auf Basis der Rekonstruktionen und Prüferberichte aller Jahre, ob der halbe Sachbezug für Ivan Kovacevic für 2023, 2024, 2025 (und Ausblick 1-9/2026, für das keine Belege vorliegen) nachweisbar ist – getrennt für Szenario A (Dienstort Ostermiething) und Szenario B (Dienstort Tirol, wöchentliche Dienstreisen nach Ostermiething lt. Angabe).
${RULES}
${KUNDEN}
Rechtslage: ${legal}
Routen: ${routes}
${perYear.filter(Boolean).map(p => `=== ${p.jahr} REKONSTRUKTION ===\n${p.rekonstruktion}\n=== ${p.jahr} PRÜFUNG ===\n${p.pruefung}`).join('\n\n')}

Liefere: je Jahr gefahrene km (belegt/Spanne), in Szenario B die Zahl wochenweise vereinbarer Dienstreisen, betriebliche Modell-km, verbleibende Privat-km und Abstand zur 6.000-km-Grenze; Ergebnis je Szenario "halber Sachbezug belegbar / nicht belegbar / nur mit weiteren Belegen"; welche Belege Szenario B tragen würden; klare Empfehlung (inkl. Abstimmung mit Steuerberatung und offenlegende Darstellung gegenüber dem Prüfer). Kein Ergebnis vortäuschen, das die Daten nicht tragen. Markdown, max. ~1.800 Wörter.`,
  { label: 'Finanzamt-Agent', phase: 'Finanzamt' })

// ---------- Phase 6: HTML ----------
phase('HTML')
const STYLE = KUNDEN + `
HTML-VORGABEN: Eine eigenständige .html-Datei (UTF-8, alles inline, keine externen Ressourcen), druckfreundlich (A4 quer, @media print), schlichtes seriöses Layout, Systemschrift. Ganz oben ein deutlich sichtbares Banner: "DATENREKONSTRUKTION nach Cyberangriff – kein Original-Fahrtenbuch. Erstellt am 01.10.2026 auf Basis von Tankkarten-, Miet- und Buchungsbelegen." Zusätzlich dezentes diagonales Wasserzeichen "REKONSTRUKTION" (CSS, auch im Druck). Statusspalte mit farbcodierten Badges: BELEGT (grün), ANGABE (blau), MODELL (violett, Hypothese), ABGELEITET (gelb), OFFEN (grau), WIDERSPRUCH (rot) – plus Text, nicht nur Farbe. Jede Zeile mit Quellenangabe (Datei + Seite). Abschnitte: 1 Stammdaten & Fahrzeuge (inkl. Dienstort-Angabe), 2 Methodik & Integritätsregeln, 3 Ereignisprotokoll (vollständige Tabelle), 4 km-Kette & Verbrauchsabgleich, 5 Wochentest Dienstreisen Hall–Ostermiething–Hall (vollständige KW-Tabelle), 6 Monatsübersicht, 7 Auffälligkeiten, 8 Ergebnis Steuerprüfer-Agent, 9 Beurteilung Sachbezug Szenario A und B (Finanzamt-Agent, Auszug für dieses Jahr), 10 Modellrekonstruktion (Hypothesen) + Prüfliste für E-Mail-Abgleich zum Abhaken, 11 Fehlende Belege / nächste Schritte, 12 Erklärung zur Erstellung (Unterschriftsfelder Fahrer und Geschäftsführung, Datum). Korrekturen des Steuerprüfers MÜSSEN eingearbeitet sein. Keine Zeilen weglassen, nichts hinzuerfinden.`

await parallel([
  ...perYear.filter(Boolean).map(p => () => agent(`Du bist HTML-Redakteur. Schreibe mit dem Write-Tool die Datei ${OUT}/Fahrtenbuch_Rekonstruktion_${p.jahr}_Kovacevic.html (eine vorhandene Datei dort ist eine Vorversion und wird vollständig ersetzt; lies sie vorher mit Read, damit Write erlaubt ist).
${RULES}
${STYLE}
=== REKONSTRUKTION ${p.jahr} ===
${p.rekonstruktion}
=== STEUERPRÜFER ${p.jahr} ===
${p.pruefung}
=== FINANZAMT-BEURTEILUNG (alle Jahre) ===
${fa}
Gib am Ende nur den Dateipfad und die Anzahl der Ereigniszeilen zurück.`,
    { label: `HTML ${p.jahr}`, phase: 'HTML' })),
  () => agent(`Du bist HTML-Redakteur. Schreibe mit dem Write-Tool die Übersichtsdatei ${OUT}/index.html (eine vorhandene Datei ist Vorversion und wird ersetzt; vorher mit Read lesen). Gleiche Gestaltung: Banner "DATENREKONSTRUKTION nach Cyberangriff – kein Original-Fahrtenbuch", Wasserzeichen, inline CSS, druckfreundlich.
${RULES}
${KUNDEN}
Inhalt: Zweck & Anlass (Cyberangriff), Fahrer/Fahrzeuge/Zeiträume, Dienstort-Angabe, Links auf Fahrtenbuch_Rekonstruktion_2023_Kovacevic.html, _2024_, _2025_, Jahresübersicht km (belegt/Spanne), Wochentest-Zusammenfassung je Jahr, Gesamtergebnis Sachbezug je Szenario A/B, Hinweis dass für 01.01.–01.10.2026 keine Belege vorlagen, Routen-Referenztabelle, Methodik, Rechtsgrundlagen mit Links. Link auf Vorversion im Ordner _Version1_DienstortOstermiething/.
=== FINANZAMT ===
${fa}
=== ROUTEN ===
${routes}
=== RECHT ===
${legal}
Gib nur den Dateipfad zurück.`, { label: 'HTML Übersicht', phase: 'HTML' }),
])

return { transaktionen: allTx.length, mitKm: allTx.filter(t => t.km_stand).length, failed, finanzamt: fa, pruefer: perYear.filter(Boolean).map(p => ({ jahr: p.jahr, pruefung: p.pruefung })) }

